content.text:
{
  "name": "HTTP任务推送器",
  "name_en": "HTTP Task Pusher",
  "manufacturer": "",
  "description": "这是一个通过 HTTP 向分布式任务队列提交任务的软件组件，可按帧生成并推送处理任务，常用于显微图像或其他逐帧数据的集群处理流程。",
  "description_en": "This is a software component that submits tasks to a distributed task queue over HTTP. It can generate and push per-frame processing tasks and is typically used in cluster workflows for microscopy images or other frame-based data.",
  "actions": [
    {
      "action_name": "auto-fileTasksForFrames",
      "description": "为新帧生成任务定义并通过 HTTP 提交到任务队列。",
      "description_en": "Generate task definitions for new frames and submit them to the task queue over HTTP."
    },
    {
      "action_name": "auto-cleanup",
      "description": "清理任务推送过程中使用的资源或内部状态。",
      "description_en": "Clean up resources or internal state used by the task pusher."
    }
  ],
  "tag_hints": [
    "HTTP task queue",
    "distributed processing",
    "cluster job submission",
    "frame-based data processing",
    "microscopy image processing"
  ]
}

